package main

import (
	"fmt"
	"math"
	"os"
	"regexp"
	"strconv"
	"strings"
)

// temmeSum (formerly gen_igam_temme_sum.py) emits the straight-line Σ_k C_k(η) u^k of
// igamTemme (see the package comment). R = exp(-z²) Σ/sqrt(2πa) is at most
// about 7% of the smaller of P and Q where igamTemme is used (|η| <= 0.34,
// a > 20), so Σ (>= 0.3) to 2^-56 relative keeps its error below 2^-60 of
// the result.
func temmeSum() {
	const eta, amin = 0.34, 20.0
	tol := math.Pow(2, -56) * 0.3
	src, err := os.ReadFile("incgamma_temme_coeffs.go")
	check(err)
	s := string(src)
	i := strings.Index(s, "var igamTemmeCoef")
	body := s[i+strings.Index(s[i:], "{"):]
	blk := regexp.MustCompile(`\{([^{}]*)\}`)
	num := regexp.MustCompile(`[-+]?\d+\.\d+(?:e[-+]\d+)?`)
	var rows [][]string
	for _, m := range blk.FindAllStringSubmatch(body, -1) {
		if ns := num.FindAllString(m[1], -1); len(ns) > 0 {
			rows = append(rows, ns)
		}
	}
	if len(rows) != 25 {
		check(fmt.Errorf("igamTemmeCoef: %d rows", len(rows)))
	}
	type row struct {
		k, deg int
		cs     []string
	}
	var out []row
	for k, r := range rows {
		mags := make([]float64, len(r))
		sum := 0.0
		for n, c := range r {
			v, err := strconv.ParseFloat(c, 64)
			check(err)
			mags[n] = math.Abs(v) * math.Pow(eta, float64(n))
			sum += mags[n]
		}
		if sum/math.Pow(amin, float64(k)) < tol {
			break
		}
		deg := len(r) - 1
		tail := 0.0
		for n := len(r) - 1; n > 0; n-- {
			tail += mags[n]
			if tail >= tol*math.Pow(amin, float64(k)) {
				break
			}
			deg = n - 1
		}
		out = append(out, row{k, deg, r[:deg+1]})
	}
	var estrin func(cs []string, v string) string
	estrin = func(cs []string, v string) string {
		if len(cs) == 1 {
			return cs[0]
		}
		m := 1
		for 2*m < len(cs) {
			m *= 2
		}
		pw := v
		if m != 1 {
			pw = fmt.Sprintf("%s%d", v, m)
		}
		return fmt.Sprintf("(%s) + %s*(%s)", estrin(cs[:m], v), pw, estrin(cs[m:], v))
	}
	powers := func(v string, n int) {
		for m := 2; m < n+1; m *= 2 {
			prev := v
			if m != 2 {
				prev = fmt.Sprintf("%s%d", v, m/2)
			}
			p("\t%s%d := %s * %s", v, m, prev, prev)
		}
	}
	p("// Code generated by %s; DO NOT EDIT.", header("testdata/gen/fitgo temme-sum", "testdata/gen/gen_igam_temme_sum.py"))
	p("")
	p("package special")
	p("")
	p("// igamTemmeSum returns Σ_k C_k(η) u^k (u = 1/a) for |η| <= %s, a >= %s:", pyG(eta), pyG(amin))
	degs := make([]string, len(out))
	maxdeg := 0
	for i, r := range out {
		degs[i] = fmt.Sprint(r.deg)
		maxdeg = max(maxdeg, r.deg)
	}
	p("// rows 0..%d, row k cut at degree %s; Estrin's scheme throughout.", len(out)-1, strings.Join(degs, ", "))
	p("func igamTemmeSum(eta, u float64) float64 {")
	powers("eta", maxdeg)
	powers("u", len(out)-1)
	for _, r := range out {
		p("\tc%d := %s", r.k, estrin(r.cs, "eta"))
	}
	cs := make([]string, len(out))
	for i, r := range out {
		cs[i] = fmt.Sprintf("c%d", r.k)
	}
	p("\treturn %s", estrin(cs, "u"))
	p("}")
}

// pyG is Python's "%g".
func pyG(f float64) string { return strconv.FormatFloat(f, 'g', 6, 64) }
